class Solution:
    def maxPrimes(self, n: int, s: int) -> list[int]:
        is_prime = bytearray(b"\x01") * (n + 1)
        if n >= 0: is_prime[0] = 0
        if n >= 1: is_prime[1] = 0
        for p in range(2, int(n ** 0.5) + 1):
            if is_prime[p]: is_prime[p * p:n + 1:p] = b"\x00" * (((n - p * p) // p) + 1)
        answer, total = [], 0
        for p in range(2, n + 1):
            if is_prime[p] and total + p <= s: answer.append(p); total += p
        return answer

